function chartSVG(series,{bars=true,line=true,width=720}={}){
  if(bars)line=false;const W=Math.max(280,Math.round(width)||720),H=bars?(W<520?180:220):(W<520?120:150),L=W<520?40:56,R=10,T=12,B=26,iw=W-L-R,ih=H-T-B,n=series.length||1,slot=iw/n;
  const bt=niceTicks(0,Math.max(0,...series.flatMap(s=>[s.out,s.inc]))),bmax=bt.hi;
  const nws=series.map(s=>s.nw),lt=niceTicks(Math.min(...nws),Math.max(...nws),3),nlo=lt.lo,nhi=lt.hi;
  const yb=v=>T+ih-(v/bmax)*ih, yl=v=>T+ih-((v-nlo)/(nhi-nlo))*ih, x=i=>L+slot*i+slot/2;
  let g='';
  for(const v of (bars?bt.ticks:lt.ticks)){const y=bars?yb(v):yl(v);g+=`<line class="cg-grid" x1="${L}" x2="${W-R}" y1="${y}" y2="${y}"/><text class="cg-axis" x="${L-6}" y="${y+4}" text-anchor="end">${compactNum(v)}</text>`}
  if(bars){const bw=Math.max(3,Math.min(24,(slot-8)/2));g+=`<line class="cg-base" x1="${L}" x2="${W-R}" y1="${T+ih}" y2="${T+ih}"/>`;series.forEach((s,i)=>{g+=`<path class="cg-out" d="${anColPath(x(i)-bw-1,yb(s.out),bw,T+ih-yb(s.out))}"/><path class="cg-in" d="${anColPath(x(i)+1,yb(s.inc),bw,T+ih-yb(s.inc))}"/>`})}
  if(line&&series.length){const pts=series.map((s,i)=>`${x(i)},${yl(s.nw)}`).join(' ');g+=`<polygon class="cg-area" points="${x(0)},${T+ih} ${pts} ${x(series.length-1)},${T+ih}"/><polyline class="cg-line" points="${pts}"/>`;series.forEach((s,i)=>{g+=`<circle class="cg-dot" cx="${x(i)}" cy="${yl(s.nw)}" r="4"/>`})}
  const every=Math.max(1,Math.ceil(series.length*40/iw));series.forEach((s,i)=>{const [y,m]=s.key.split('-');if((series.length-1-i)%every===0)g+=`<text class="cg-label" x="${x(i)}" y="${H-8}" text-anchor="middle">${m==='01'?y:Number(m)+'月'}</text>`;g+=`<rect class="cg-hit" data-chart-month="${s.key}" x="${L+slot*i}" y="${T}" width="${slot}" height="${ih+B}"/>`});
  return `<svg class="cg ${bars?'cg-bars':'cg-nw'}" viewBox="0 0 ${W} ${H}" role="img" aria-label="${bars?'每月支出與收入':'月底淨資產'}">${g}</svg>`;
}
function chartLegend(s){if(!s)return '';const [y,m]=s.key.split('-');return `<span class="cg-key">${y} 年 ${Number(m)} 月</span><span><i class="cg-swatch nw"></i>淨資產 ${money(s.nw)}</span><span><i class="cg-swatch out"></i>支出 −${money(s.out).replace(/^-/,'')}</span><span><i class="cg-swatch in"></i>收入 +${money(s.inc)}</span>`}
function mountChart(el,series,opts){if(!el)return;el.classList.add('chart-svg');const both=opts?.bars&&opts?.line;el.innerHTML=both?`<div class="cg-key-row"><span><i class="cg-swatch out"></i>支出</span><span><i class="cg-swatch in"></i>收入</span></div>${chartSVG(series,{bars:true,width:el.clientWidth})}<div class="cg-sub">月底淨資產</div>${chartSVG(series,{bars:false,line:true,width:el.clientWidth})}<div class="cg-legend">${chartLegend(series[series.length-1])}</div>`:`${chartSVG(series,{...opts,width:el.clientWidth})}<div class="cg-legend">${chartLegend(series[series.length-1])}</div>`;const legend=el.querySelector('.cg-legend');const show=e=>{const k=e.target?.dataset?.chartMonth;if(!k)return;const s=series.find(x=>x.key===k);if(s&&legend)legend.innerHTML=chartLegend(s);el.querySelectorAll('.cg-hit').forEach(r=>r.classList.toggle('active',r.dataset.chartMonth===k))};el.onmouseover=show;el.onclick=show}
function render(){if(typeof prefSyncPull==='function'&&prefSyncPull())applyPrefs();if(typeof inboxPull==='function')inboxPull();if(typeof reconMigrate==='function'&&reconMigrate(state)){save()}if(typeof autoPostRecurring==='function'&&autoPostRecurring()){save()}if(typeof autoPostDue==='function'&&autoPostDue()){save()}if(typeof catIconAuto==='function'&&catIconAuto()){save()}if(typeof rewardRun==='function'&&rewardRun()){save()}if(typeof autoPayRun==='function'&&autoPayRun()){save()}renderMetrics();renderChart();renderRecent();renderCalendar();renderDaily();renderCards();renderTransactions();renderAccounts();if(typeof renderBank==='function')renderBank();renderAccountDetail();renderCardSettings();renderBars();renderBudgets();renderRecurring();renderProjects();renderCategories();renderLoans();fillFilters();if(typeof renderReminders==='function')renderReminders();if(typeof renderSubscriptions==='function')renderSubscriptions();if(typeof renderYearly==='function')renderYearly();if(typeof renderReconMode==='function')renderReconMode();if(typeof renderNotice==='function'){renderNotice();renderFullCal();renderQuickAccess()}}
function renderMetrics(){const key=monthKey(),cur=monthStats(key),prev=monthStats(addMonths(key,-1)),[nwPrev,nwCur]=netWorthAt([addMonths(key,-1),key]),out=cur.out,inc=cur.inc,nw=netWorth(state.accounts);mBalance.textContent=money(nwCur);mExpense.textContent=money(out);mIncome.textContent=money(inc);{const conv=nw.conv.reduce((m,[c,v,t])=>{m[c]=m[c]||[0,0];m[c][0]+=v;m[c][1]+=t;return m},{}),parts=[];for(const [c,[v,t]] of Object.entries(conv))parts.push(`${acctMoney(v,{currency:c})} ≈ ${money(t)}`);const miss=Object.entries(nw.missing).map(([c,v])=>acctMoney(v,{currency:c}));if(parts.length||miss.length)refreshFx();const fxNote=[parts.length?`含外幣 ${parts.join(' · ')}（匯率 ${fxDateLabel()}）`:'',miss.length?`未計入（尚無匯率）：${miss.join(' · ')}`:''].filter(Boolean).join('；');mBalanceDelta.textContent=deltaText(nwCur,nwPrev)+(fxNote?' · 含外幣換算':'');mBalanceDelta.title=fxNote;setDeltaClass(mBalanceDelta,nwCur-nwPrev);}mExpenseDelta.textContent=deltaText(out,prev.out);setDeltaClass(mExpenseDelta,out-prev.out,true);mIncomeDelta.textContent=deltaText(inc,prev.inc);setDeltaClass(mIncomeDelta,inc-prev.inc)}
function setDeltaClass(el,d,inverse){if(!el?.classList)return;el.classList.remove('delta-up','delta-down');if(d)el.classList.add((d>0)!==!!inverse?'delta-up':'delta-down')}
function renderChart(){const n=Number(document.getElementById('chartRange')?.value||12)||12;mountChart(cashflowChart,chartSeries(n),{bars:true,line:true});if(trendChart)mountChart(trendChart,chartSeries(12),{bars:false,line:true})}
function txRow(t){let c=cat(t.category);return `<div class="row"><div class="row-left"><div class="mini-icon">${catIconHTML(c)}</div><div><b>${esc(t.name)}</b><div class="hint">${esc(t.merchant||'')} · ${esc(acct(t.account).name)}</div></div></div><div class="amount" style="color:${t.kind==='expense'?'var(--accent)':t.kind==='income'?'var(--green)':''}">${t.kind==='expense'?'−':t.kind==='income'?'+':''}${money(t.amount)}</div></div>`}
