const WEEKDAYS=['週日','週一','週二','週三','週四','週五','週六'];
function renderCalendar(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth();const first=calendarLead(y,m),days=new Date(y,m+1,0).getDate(),today=isoDate(new Date());let html='';for(let i=0;i<first;i++)html+='<div></div>';for(let n=1;n<=days;n++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`,has=state.transactions.some(t=>t.date===date),dt=has?dayTotals(date):null,wd=new Date(y,m,n).getDay();html+=`<button type="button" class="day ${date===selectedDate?'sel':''} ${date===today?'today':''} ${wd===0||wd===6?'wkend':''}" data-date="${date}"><span class="day-num">${n}</span>${dt&&dt.net?`<small class="day-amt ${dt.net<0?'neg':'pos'}">${dt.net<0?'−':'+'}${compactNum(Math.abs(dt.net))}</small>`:has?'<i class="dot"></i>':''}</button>`}calendarGrid.innerHTML=html;calendarGrid.querySelectorAll('.day').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;renderCalendar();renderDaily()});monthTitle.textContent=`${y} 年 ${m+1} 月`;periodLabel.textContent=`${y}/${String(m+1).padStart(2,'0')}`}
function renderDaily(){const ts=state.transactions.filter(t=>t.date===selectedDate&&!(t.rewardOf&&prefOn('hideRewards'))).sort((a,b)=>(prefs().dayOrder==='asc'?-1:1)*String(b.time||'').localeCompare(String(a.time||''))),key=selectedDate.slice(0,7),ms=monthStats(key),pt=monthProjectTotal(key),dt=dayTotals(selectedDate),[yy,mm,dd]=selectedDate.split('-').map(Number),wd=WEEKDAYS[new Date(yy,mm-1,dd).getDay()];const box=document.getElementById('monthStats');if(box)box.innerHTML=`<div><b>${mm} 月統計</b>${pt?`<small>專案總額 ${money(pt)}</small>`:''}</div><div class="month-stats-amt"><span class="expense-text">${money(ms.out)}</span> · <span class="income-text">${money(ms.inc)}</span></div>${projHomeHTML(selectedDate)}`;dailyCaption.textContent=`${yy}/${pad2(mm)}/${pad2(dd)}（${wd}）${ts.length?` · 支出 ${money(dt.out)} · 收入 ${money(dt.inc)}`:''}`;dailyList.innerHTML=ts.length?ts.map(t=>{const v=txSigned(t),proj=t.project?state.projects.find(p=>String(p.id)===String(t.project)):null,sub=[t.merchant||t.person||'',t.time||'',(Array.isArray(t.tags)?t.tags.map(x=>'#'+x).join(' '):'')].filter(Boolean);return `<div class="day-row" data-txid="${esc(t.id)}"><div class="tx-icon">${catIconHTML(cat(t.category))}</div><div class="day-main"><b>${esc(t.name)}${t.pending?' <span class="chip pending">待完成</span>':''}</b><small>${esc(sub.join(' · ')||txTypeLabel(t))}</small></div><div class="day-side"><b class="${v<0?'expense-text':v>0?'income-text':''}">${v>0?'+':v<0?'−':''}${money(Math.abs(v||Number(t.amount||0)))}</b><span class="chips">${proj?`<i>${esc(proj.name)}</i>`:''}<i>${acctName(acct(t.account))}</i></span></div></div>`}).join(''):'<div class="empty">當日沒有交易</div>';dailyList.querySelectorAll('.day-row').forEach(r=>r.onclick=()=>openDetail(r.dataset.txid))}
function renderTransactions(){let q=(txSearch.value||'').toLowerCase(),type=txType.value,ca=txCategory.value,ac=txAccount.value;let ts=state.transactions.filter(t=>(!q||`${esc(t.name)} ${esc(t.merchant||'')} ${esc(t.note||'')}`.toLowerCase().includes(q))&&(type==='all'||t.kind===type)&&(ca==='all'||t.category===ca)&&(ac==='all'||t.account===ac)).sort((a,b)=>b.date.localeCompare(a.date));let count=ts.length,out=ts.filter(t=>t.kind==='expense').reduce((s,t)=>s+t.amount,0),inc=ts.filter(t=>t.kind==='income').reduce((s,t)=>s+t.amount,0);let summary=`<div class="tx-toolbar"><div class="tx-summary"><span>共 <b>${count}</b> 筆</span><span>支出 <b class="expense-text">${money(out)}</b></span><span>收入 <b class="income-text">${money(inc)}</b></span></div></div>`;let groups={};ts.forEach(t=>(groups[t.date]??=[]).push(t));let body=Object.entries(groups).map(([date,list])=>{let dayOut=list.filter(t=>t.kind==='expense').reduce((s,t)=>s+t.amount,0),dayIn=list.filter(t=>t.kind==='income').reduce((s,t)=>s+t.amount,0);return `<div class="tx-group"><div class="tx-group-head"><b>${date}</b><span>${dayOut?'支出 '+money(dayOut):''}${dayIn?' · 收入 '+money(dayIn):''}</span></div>${list.map(t=>{let c=cat(t.category),amount=t.kind==='expense'?'−'+money(t.amount):t.kind==='income'?'+'+money(t.amount):money(t.amount);return `<div class="tx-entry" data-txid="${t.id}"><div class="tx-icon">${catIconHTML(c)}</div><div><div class="tx-name">${esc(t.name)}</div><div class="tx-meta">${esc(t.merchant||'—')} · ${esc(acct(t.account).name)}${esc(t.project?' · '+(state.projects.find(p=>String(p.id)===String(t.project))?.name||''):'')}</div></div><div class="tx-type">${t.kind==='expense'?'支出':t.kind==='income'?'收入':'轉帳'}</div><div class="tx-actions"><b class="tx-amount ${t.kind==='expense'?'expense-text':t.kind==='income'?'income-text':''}">${amount}</b></div></div>`}).join('')}</div>`}).join('')||'<div class="panel empty">找不到符合條件的交易</div>';txTable.innerHTML=summary+`<div class="tx-groups">${body}</div>`;document.querySelectorAll('.tx-entry').forEach(row=>row.onclick=()=>openDetail(row.dataset.txid))}
function openDetail(id){let t=state.transactions.find(x=>String(x.id)===String(id));if(!t)return;window.detailId=t.id;let c=cat(t.category),project=t.project?(state.projects.find(p=>String(p.id)===String(t.project))?.name||'—'):'無專案';detailTitle.textContent=t.name;detailSubtitle.textContent=fmtDate(t.date);detailGrid.innerHTML=`<div class="detail-box"><small>金額</small><b class="${t.kind==='expense'?'expense-text':t.kind==='income'?'income-text':''}">${t.kind==='expense'?'−':t.kind==='income'?'+':''}${money(t.amount)}</b></div>${t.feeIncluded&&(t.fee||t.discount)?`<div class="detail-box"><small>含費用／折扣</small><b>${t.fee?esc(t.feeName||'手續費')+' '+money(t.fee):''}${t.fee&&t.discount?'　':''}${t.discount?esc(t.discountName||'折扣')+' −'+money(t.discount):''}</b></div>`:''}<div class="detail-box"><small>類型</small><b>${t.kind==='expense'?'支出':t.kind==='income'?'收入':'轉帳'}</b></div><div class="detail-box"><small>分類</small><b>${esc(c.icon)} ${esc(c.name)}</b></div><div class="detail-box"><small>帳戶</small><b>${esc(acct(t.account).name)}</b></div><div class="detail-box"><small>專案</small><b>${project}</b></div><div class="detail-box"><small>商家</small><b>${esc(t.merchant||'—')}</b></div><div class="detail-box detail-wide"><small>備註</small><b>${esc(t.note||'—')}</b></div>`;detailBg.classList.add('open')}
