/* V25.8 — full loan page + CSV receivable/payable integration */
function loanDirection(l){return l&&l.direction==='payable'?'payable':'receivable'}
function loanOutstanding(l){return Math.max(0,Number(l?.amount||0)-Number(l?.paid||0))}
function loanStatus(l){return l?.status==='stopped'?'stopped':loanOutstanding(l)<=0?'completed':'active'}
function loanLabel(dir){return dir==='payable'?'應付':'應收'}
function loanActionLabel(dir){return dir==='payable'?'還款':'收款'}
function loanEnsureModel(l){
  if(!l)return l;
  l.direction=loanDirection(l); l.amount=Math.max(0,Number(l.amount||0)); l.paid=Math.max(0,Math.min(l.amount,Number(l.paid||0)));
  l.payments=Array.isArray(l.payments)?l.payments:[];
  l.status=loanStatus(l);
  return l;
}
function loanNetSummary(){
  const ls=(state.loans||[]).map(loanEnsureModel);
  const receivable=ls.filter(l=>loanDirection(l)==='receivable'&&loanStatus(l)!=='stopped'&&!l.excludeNet).reduce((s,l)=>s+loanOutstanding(l),0);
  const payable=ls.filter(l=>loanDirection(l)==='payable'&&loanStatus(l)!=='stopped'&&!l.excludeNet).reduce((s,l)=>s+loanOutstanding(l),0);
  return {receivable,payable,net:receivable-payable,active:ls.filter(l=>loanStatus(l)==='active').length,completed:ls.filter(l=>loanStatus(l)==='completed').length};
}
// V25.19: loan editing. Every loan / loanPayment transaction carries loanId; deleting reverses the
// exact account effect the transaction applied (imported rows keep balanceEffect incl. fee/discount).
function loanTxs(loan){return (state.transactions||[]).filter(t=>String(t.loanId)===String(loan.id))}
function loanTxEffect(t){if(t.imported&&t.balanceEffect!==undefined)return Number(t.balanceEffect)||0;const a=Math.abs(Number(t.amount||0));if(t.kind==='loan')return t.loanAction==='lend'?-a:a;if(t.kind==='loanPayment')return t.loanDirection==='receivable'?a:-a;return 0}
function loanPaymentTx(loan,p){const list=loanTxs(loan).filter(t=>t.kind==='loanPayment');return list.find(t=>t.paymentId!==undefined&&String(t.paymentId)===String(p.id))||list.find(t=>t.paymentId===undefined&&t.date===p.date&&Number(t.amount)===Number(p.amount)&&String(t.account)===String(p.account))||null}
function reverseLoanTx(t){const a=state.accounts.find(x=>String(x.id)===String(t.account));if(a)a.balance=Math.round((Number(a.balance||0)-loanTxEffect(t))*100)/100;state.transactions=state.transactions.filter(x=>x!==t)}
function refreshLoanStatus(loan){if(loan.status!=='stopped')loan.status=loanOutstanding(loan)<=0?'completed':'active'}
function removeLoan(loan){const txs=loanTxs(loan);txs.forEach(reverseLoanTx);state.loans=state.loans.filter(l=>l!==loan);return txs.length}
function removeLoanPayment(loan,p){if(loan.historicalOnly)return {removedLoan:true,txCount:removeLoan(loan)};const t=loanPaymentTx(loan,p);if(t)reverseLoanTx(t);loan.payments=loan.payments.filter(x=>x!==p);loan.paid=Math.max(0,Number(loan.paid||0)-Number(p.amount||0));refreshLoanStatus(loan);return {removedLoan:false,txFound:!!t}}
function loanEffectText(txs){const by=new Map();for(const t of txs){const a=acct(t.account);const k=a.id?acctName(a):'未知帳戶';by.set(k,(by.get(k)||0)-loanTxEffect(t))}return [...by].filter(([,v])=>Math.abs(v)>=0.005).map(([k,v])=>`${k} ${v>0?'+':''}${money(v)}`).join('、')||'無'}
function loanFilterMatch(l,filter){const st=loanStatus(l);if(filter==='completed')return st==='completed'||st==='stopped';if(filter==='upcoming')return loanNotStarted(l);if(filter==='active')return st==='active'&&!loanNotStarted(l);if(filter==='receivable')return loanDirection(l)==='receivable'&&st==='active';if(filter==='payable')return loanDirection(l)==='payable'&&st==='active';return true}
function renderLoans(){
  const cards=document.getElementById('loanSummaryCards'), grid=document.getElementById('loanGrid'), detail=document.getElementById('loanDetailPanel'), count=document.getElementById('loanCount');
  if(!grid)return;
  (state.loans||[]).forEach(loanEnsureModel);
  const sum=loanNetSummary();
  if(cards)cards.innerHTML=`<article class="loan-summary-card receivable"><small>應收款項</small><strong>${money(sum.receivable)}</strong><span>尚未收回的借款／代付款</span></article><article class="loan-summary-card payable"><small>應付款項</small><strong>${money(sum.payable)}</strong><span>尚未償還的借款／負債</span></article><article class="loan-summary-card net"><small>借還款淨額</small><strong>${money(sum.net)}</strong><span>${sum.active} 筆進行中 · ${sum.completed} 筆已完成</span></article>`;
  const filter=window.__mozeLoanFilter||'all';
  document.querySelectorAll('[data-loan-filter]').forEach(b=>b.classList.toggle('active',b.dataset.loanFilter===filter));
  const chips=loanPersonChips(filter),ls=(state.loans||[]).filter(l=>loanFilterMatch(l,filter)&&loanPersonOk(l));
  if(count)count.textContent=`${ls.length} 筆`;
  const groups=new Map();
  ls.forEach(l=>{const p=l.person||'未指定對象';if(!groups.has(p))groups.set(p,[]);groups.get(p).push(l)});
  if(!ls.length){grid.innerHTML=chips+'<div class="panel empty">目前沒有符合條件的借還款</div>'}
  else{
    grid.innerHTML=chips+[...groups.entries()].map(([person,list])=>{
      const personNet=list.reduce((s,l)=>s+(loanDirection(l)==='receivable'?1:-1)*loanOutstanding(l),0);
      const active=list.filter(l=>loanStatus(l)==='active').length;
      return `<div class="loan-person-group"><div class="loan-person-head"><div class="loan-person-title"><b>${esc(person)}</b><button type="button" class="ghost" data-person-history="${esc(person)}" aria-label="借還款歷史">歷史</button><button type="button" class="ghost" data-person-rename="${esc(person)}" aria-label="修改對象名稱">✎</button><span>${active} 筆進行中 · ${list.length-active} 筆已完成</span></div><div class="loan-person-total"><b class="${personNet>=0?'income-text':'expense-text'}">${personNet>=0?'+':''}${money(personNet)}</b><span>未結餘額</span></div></div>${list.map(l=>{const dir=loanDirection(l),outstanding=loanOutstanding(l),pct=l.amount?Math.min(100,(l.paid/l.amount)*100):100;const done=loanStatus(l)!=='active';return `<div class="loan-row" data-loan-id="${l.id}"><span class="loan-direction ${dir}">${done?'':`<button type="button" class="loan-check ${window.__loanSel?.has(String(l.id))?'on':''}" data-loan-check="${l.id}" aria-label="選取">✓</button>`}${l.existing?(dir==='payable'?'既有欠款':'既有應收'):loanLabel(dir)}</span><div class="loan-main"><b>${esc(l.name||((dir==='receivable'?'借出':'借入')+' · '+person))}</b><span>${l.date||'未設定日期'}${esc(l.account?' · '+acct(l.account).name:'')}${l.dueDate?' · 到期 '+l.dueDate:''}</span></div><div class="loan-progress"><div class="loan-progress-track"><i style="width:${pct}%"></i></div><div class="loan-progress-label"><span>已 ${money(l.paid)}</span><span>${pct.toFixed(0)}%</span></div></div><div class="loan-row-amount"><b class="${done?'':'income-text'}">${money(outstanding)}</b><span>${done?'已完成':'剩餘'}</span></div><button type="button" class="loan-action" data-loan-action="${l.id}" ${done?'disabled':''}>${loanActionLabel(dir)}</button></div>`}).join('')}</div>`;
    }).join('');
  }
  renderLoanDetail();renderLoanBulk();
  // Keep the overview compact but useful.
  renderLoanTracking();
}
function renderLoanDetail(){
  const panel=document.getElementById('loanDetailPanel'); if(!panel)return;
  const id=window.__mozeSelectedLoanId; const loan=(state.loans||[]).find(l=>String(l.id)===String(id));
  if(!loan){panel.hidden=true;panel.innerHTML='';return;}
  loanEnsureModel(loan); panel.hidden=false;
  const dir=loanDirection(loan), out=loanOutstanding(loan), payAccounts=(state.accounts||[]).filter(a=>a.type!=='card');
  const defaultAccount=loan.account||payAccounts[0]?.id||'';
  panel.innerHTML=`<div class="loan-detail-head"><div class="loan-detail-title"><div class="loan-detail-icon">${dir==='payable'?'↙':'↗'}</div><div><h3>${esc(loan.person||'未指定對象')}</h3><p>${loanLabel(dir)} · ${esc(loan.name||'借還款記錄')}${loan.date?' · '+loan.date:''}${loan.dueDate?' · 到期 '+loan.dueDate:''}</p></div></div><button type="button" class="secondary" data-loan-close>關閉</button></div><div class="loan-detail-summary"><div class="loan-detail-box"><span>原始金額</span><b>${money(loan.amount)}</b></div><div class="loan-detail-box"><span>已${dir==='payable'?'還':'收'}</span><b>${money(loan.paid)}</b></div><div class="loan-detail-box"><span>剩餘${dir==='payable'?'應還':'應收'}</span><b class="${out?'':'income-text'}">${money(out)}</b></div></div>${out?`<div class="loan-payment-area"><h4>${loanActionLabel(dir)}</h4><div class="loan-payment-form"><label>金額<div class="loan-payment-amount"><input id="loanPaymentAmount" type="number" min="1" step="any" value="${out}"><button type="button" data-loan-full>全額</button></div></label><label>實際帳戶<select id="loanPaymentAccount">${payAccounts.map(a=>`<option value="${a.id}" ${String(a.id)===String(defaultAccount)?'selected':''}>${acctName(a)} · ${acctMoney(a.balance,a)}</option>`).join('')}</select></label><label>日期<input id="loanPaymentDate" type="date" value="${selectedDate}"></label><label>多出的金額<select id="loanPaymentOver"><option value="track">繼續追蹤（另記反向款項）</option><option value="settle">視為結清</option></select></label><label>金額不足時<select id="loanPaymentUnder"><option value="track">繼續追蹤剩餘</option><option value="settle">視為結清（停止追蹤）</option></select></label><label>備註<input id="loanPaymentNote" type="text" placeholder="可留空"></label></div><div class="loan-payment-actions"><button type="button" class="primary" data-loan-confirm="${loan.id}">${loanActionLabel(dir)}</button></div></div>`:'<div class="loan-payment-area"><div class="empty">這筆款項已完成</div></div>'}<div class="loan-history"><div class="loan-history-head"><h4 style="margin:0">${loanActionLabel(dir)}記錄</h4><span class="hint" style="margin:0">${loan.payments.length} 筆</span></div><div class="loan-history-list">${loan.payments.length?loan.payments.slice().reverse().map(p=>`<div class="loan-history-row"><span>${p.date||''}</span><div>${esc(p.account?acct(p.account).name:'未指定帳戶')}${p.note?`<div class="hint" style="margin:2px 0 0">${esc(p.note)}</div>`:''}</div><b>${money(p.amount)}</b><button type="button" class="loan-pay-del" data-loan-pay-del="${esc(p.id)}" aria-label="刪除這筆記錄" title="刪除這筆記錄">刪除</button></div>`).join(''):'<div class="empty">尚無收還款記錄</div>'}</div></div>${String(window.__mozeLoanEditId)===String(loan.id)?`<div class="loan-edit-form"><h4>編輯借還款</h4><div class="loan-payment-form"><label>對象<input id="loanEditPerson" value="${esc(loan.person||'')}"></label><label>名稱<input id="loanEditName" value="${esc(loan.name||'')}"></label><label>到期日<input id="loanEditDue" type="date" value="${esc(loan.dueDate||'')}"></label><label>備註<input id="loanEditNote" value="${esc(loan.note||'')}"></label></div><p class="hint">金額、帳戶與日期不能直接修改，以免帳戶餘額不一致；請刪除後重新建立。</p><div class="loan-payment-actions"><button type="button" class="secondary" data-loan-edit-cancel>取消</button><button type="button" class="primary" data-loan-edit-save="${loan.id}">儲存</button></div></div>`:''}<div class="loan-detail-actions"><span class="hint" style="margin:0">停止追蹤後會移到「已完成」，不會刪除歷史資料。刪除會一併刪除相關交易並還原帳戶餘額。</span><div class="loan-detail-buttons"><button type="button" class="secondary" data-loan-edit="${loan.id}">編輯</button>${loanStatus(loan)==='stopped'?`<button type="button" class="secondary" data-loan-resume="${loan.id}">恢復追蹤</button>`:`<button type="button" class="secondary loan-stop" data-loan-stop="${loan.id}" ${loanStatus(loan)==='active'?'':'disabled'}>停止追蹤</button>`}<button type="button" class="secondary danger-btn" data-loan-delete="${loan.id}">刪除</button></div></div>${loanExtraHTML(loan)}`;
}
function selectLoan(id){window.__mozeSelectedLoanId=id;renderLoans();document.getElementById('loanDetailPanel')?.scrollIntoView({behavior:'smooth',block:'nearest'})}
function openEntity(type,editing=null){entityFormEl.dataset.editId=editing?.id||'';
  const fields={account:[['name','帳戶名稱'],['balance','初始餘額']],budget:[['limit','預算金額']],project:[['name','專案名稱'],['budget','預算']],category:[['name','分類名稱'],['icon','Icon']],recurring:[['name','名稱'],['amount','金額'],['next','下次日期']],loan:[['person','對象'],['amount','金額']]};
  entityTitleEl.textContent='新增'+({account:'帳戶',budget:'預算',project:'專案',category:'分類',recurring:'週期交易',loan:'借還款'}[type]);
  if(type==='account'){
    entityFieldsEl.innerHTML=`${acctImageFieldHTML({})}<div class="entity-field"><label>帳戶名稱<input name="name" required></label></div><div class="entity-field"><label>類型<select name="accountType"><option value="bank">銀行</option><option value="cash">現金</option><option value="ewallet">電子支付</option><option value="broker">證券戶</option><option value="foreign">外幣</option><option value="card">信用卡</option></select></label></div><div class="form-grid"><label>初始餘額／目前欠款<input name="balance" type="number" step="any" value="0" required></label>${acctCurrencyField('TWD',false)}</div><div class="form-grid form-grid-1"><label>備註<input name="anote" maxlength="100" placeholder="可留空"></label></div>${acctGroupFieldHTML({})}${acctNewOptionsHTML()}${acctCustomCurHTML({})}${acctBankFieldHTML({},false)}<div id="newCardFields" style="display:none">${acctCardFieldsHTML({limit:50000},true)}</div>`;
    entityFieldsEl.querySelector('[name=accountType]').onchange=e=>{document.getElementById('newCardFields').style.display=e.target.value==='card'?'block':'none';const bf=entityFieldsEl.querySelector('[data-acct-bank-field]');if(bf)bf.hidden=!(e.target.value==='card'||e.target.value==='foreign')};
  }else if(type==='loan'){
    entityFieldsEl.innerHTML=`<div class="entity-help">借給別人選「應收」；向別人借錢選「應付」。建立後會同步調整實際帳戶餘額，但不會算成一般支出／收入。</div><div class="seg"><label><input type="radio" name="direction" value="receivable" checked>應收・借出</label><label><input type="radio" name="direction" value="payable">應付・借入</label></div><label class="proj-archive"><input type="checkbox" name="loanExisting"> 既有款項（早已發生，只登記目前剩餘金額，不動帳戶）</label><div class="form-grid"><label>對象<input name="person" required placeholder="例如：小明"></label><label>金額<input name="amount" type="number" min="1" step="1" required></label><label>實際帳戶<select name="account" required>${state.accounts.filter(a=>a.type!=='card').map(a=>`<option value="${a.id}">${acctName(a)} · ${acctMoney(a.balance,a)}</option>`).join('')}</select></label><label>日期<input name="date" type="date" value="${selectedDate}" required></label><label>到期日<input name="dueDate" type="date"></label><label>名稱<input name="loanName" placeholder="例如：借朋友生活費"></label></div><div class="entity-field"><label>備註<input name="note" placeholder="可留空"></label></div>`;
    entityFieldsEl.querySelectorAll('input[name=direction]').forEach(r=>r.onchange=()=>{});
  }else if(type==='accountEdit'){
    entityTitleEl.textContent='管理帳戶';entityFieldsEl.innerHTML=acctEditFormHTML(editing);
  }else if(type==='accountAdjust'){
    entityTitleEl.textContent='調整餘額';entityFieldsEl.innerHTML=acctAdjustFormHTML(editing);
  }else if(type==='project'){
    if(editing)entityTitleEl.textContent='編輯專案';entityFieldsEl.innerHTML=projFormHTML(editing);
  }else if(type==='category'){
    entityTitleEl.textContent=editing&&!editing.__new?'編輯分類':editing?.parentId?'新增子分類':'新增分類';entityFieldsEl.innerHTML=catFormHTML(editing);catFormBind(entityFieldsEl);
  }else if(type==='categoryDelete'){
    entityTitleEl.textContent='刪除分類';entityFieldsEl.innerHTML=catDeleteFormHTML(editing);
  }else if(type==='budget'){
    if(editing)entityTitleEl.textContent='編輯預算';entityFieldsEl.innerHTML=budgetFormHTML(editing);budgetFormSync(entityFieldsEl);entityFieldsEl.querySelectorAll('input[name=bscope]').forEach(r=>r.onchange=()=>budgetFormSync(entityFieldsEl));
  }else if(type==='recurring'){
    const r=editing?normRecurring({...editing}):{kind:'expense',freq:'month',interval:1,start:selectedDate,end:{type:'never'}};if(editing)entityTitleEl.textContent='編輯週期交易';
    const opt=(v,l,cur)=>`<option value="${v}" ${String(v)===String(cur)?'selected':''}>${l}</option>`;
    entityFieldsEl.innerHTML=`<div class="seg"><label><input type="radio" name="rkind" value="expense" ${r.kind==='expense'?'checked':''}>支出</label><label><input type="radio" name="rkind" value="income" ${r.kind==='income'?'checked':''}>收入</label><label><input type="radio" name="rkind" value="transfer" ${r.kind==='transfer'?'checked':''}>轉帳</label></div><div class="form-grid"><label>名稱<input name="name" required value="${esc(r.name||'')}" placeholder="例如：房租"></label><label>金額<input name="amount" type="number" min="0" step="any" required value="${r.amount??''}"></label><label>分類<select name="category">${state.categories.filter(c=>c.kind!=='prefs').map(c=>opt(c.id,`${esc(c.icon)} ${esc(c.name)}`,r.category)).join('')}</select></label><label>帳戶<select name="account">${state.accounts.map(a=>opt(a.id,acctName(a),r.account)).join('')}</select></label><label>商家<input name="merchant" value="${esc(r.merchant||'')}" placeholder="可留空"></label><label>開始日期<input name="start" type="date" required value="${esc(r.start||selectedDate)}"></label><label>頻率<select name="freq">${opt('day','天',r.freq)}${opt('week','週',r.freq)}${opt('month','月',r.freq)}${opt('year','年',r.freq)}</select></label><label>每隔<input name="interval" type="number" min="1" step="1" value="${r.interval||1}"></label><label>結束<select name="endType">${opt('never','無限期',r.end.type)}${opt('count','共幾期',r.end.type)}${opt('date','到某天',r.end.type)}</select></label><label>結束值<input name="endValue" value="${esc(r.end.value??'')}" placeholder="期數或 YYYY-MM-DD"></label><label class="check rc-auto"><input type="checkbox" name="rauto" ${r.auto?'checked':''}>到期自動入帳（開啟 App 時補記已到期的各期）</label></div>${recurringOptsHTML(r)}${editing?`<p class="hint">下一次：${esc(r.next)}。修改開始日期會把下一次重設為開始日期。</p>`:''}`;
  }else{
    entityFieldsEl.innerHTML=(fields[type]||[]).map(([n,l])=>`<div class="entity-field"><label>${l}<input name="${n}" type="${n==='amount'||n==='balance'||n==='budget'||n==='limit'?'number':n==='next'?'date':'text'} required></label></div>`).join('');
  }
  entityFormEl.dataset.type=type;entityBgEl.classList.add('open');
}
async function submitEntity(e){
  e.preventDefault();let f=new FormData(entityFormEl),type=entityFormEl.dataset.type;
  if(type==='account'){let at=f.get('accountType')||'bank',bal=Number(f.get('balance')||0),cur=String(f.get('acur')||'TWD').trim().toUpperCase(),nm=String(f.get('name')||'').trim();if(!nm){alert('請輸入帳戶名稱');return}if(!/^[A-Z]{2,6}$/.test(cur)){alert('幣別請輸入 2～6 個英文字母，例如 TWD、USD');return}if(state.accounts.some(a=>a.name===nm&&acctCur(a)===cur)){alert(`已經有「${nm}（${cur}）」`);return}state.accounts.push({id:id(),name:nm,currency:cur,note:String(f.get('anote')||'').trim()||undefined,type:at,balance:at==='card'?-Math.abs(bal):bal,...(at==='card'?acctCardSettingsFromForm(f):(at==='foreign'||cur!=='TWD')?acctBankFromForm(f):{}),...acctOptionsFromForm(f,at),...acctImageFromForm(f),...acctCustomCurFromForm(f)});}
  if(type==='category'){const editId=entityFormEl.dataset.editId,old=editId?state.categories.find(c=>String(c.id)===String(editId)):null,res=catFromForm(f,old);if(res.error){alert(res.error);return}if(old){if(!old.parentId&&old.kind!==res.category.kind)catChildren(old).forEach(k=>k.kind=res.category.kind);state.categories=state.categories.map(c=>c===old?res.category:c)}else{res.category.order=catSiblings(res.category).length;state.categories.push(res.category)}}
  if(type==='categoryDelete'){const editId=entityFormEl.dataset.editId,c=state.categories.find(x=>String(x.id)===String(editId)),to=f.get('ctarget');if(!c||!to){alert('請選擇要改用的分類');return}catReassign(c.id,to);state.categories=state.categories.filter(x=>x!==c)}
  if(type==='accountEdit'){const editId=entityFormEl.dataset.editId,old=state.accounts.find(a=>String(a.id)===String(editId));if(!old)return;const res=acctFromEditForm(f,old);if(res.error){alert(res.error);return}state.accounts=state.accounts.map(a=>a===old?res.account:a);if(res.account.type!=='card'&&String(selectedCreditCardId)===String(old.id))selectedCreditCardId=null}
  if(type==='accountAdjust'){const editId=entityFormEl.dataset.editId,a=state.accounts.find(x=>String(x.id)===String(editId));if(!a)return;const v=Number(f.get('abalance'));if(!Number.isFinite(v)){alert('請輸入實際餘額');return}if(!acctAdjustTo(a,v,f.get('adate'),String(f.get('anote')||'').trim(),f.get('atime'),!!f.get('akeep'))){alert('餘額沒有變動');return}}
  if(type==='project'){const editId=entityFormEl.dataset.editId,old=editId?state.projects.find(p=>String(p.id)===String(editId)):null,res=projFromForm(f,old);if(res.error){alert(res.error);return}if(old)state.projects=state.projects.map(p=>p===old?res.project:p);else state.projects.push(res.project)}
  if(type==='budget'){const editId=entityFormEl.dataset.editId,old=editId?state.budgets.find(b=>String(b.id)===String(editId)):null,res=budgetFromForm(f,old);if(res.error){alert(res.error);return}if(old)state.budgets=state.budgets.map(b=>b===old?res.budget:b);else state.budgets.push(res.budget)}
  if(type==='recurring'){const editId=entityFormEl.dataset.editId,old=editId?state.recurring.find(r=>String(r.id)===String(editId)):null,start=f.get('start')||selectedDate,endType=f.get('endType')||'never',endRaw=String(f.get('endValue')||'').trim();if(endType==='count'&&!(Number(endRaw)>=1)){alert('請輸入結束期數（至少 1）');return}if(endType==='date'&&!/^\d{4}-\d{2}-\d{2}$/.test(endRaw)){alert('請以 YYYY-MM-DD 輸入結束日期');return}const r={...(old||{id:id(),seq:0,posted:0}),auto:!!f.get('rauto'),name:f.get('name'),amount:Math.abs(Number(f.get('amount')||0)),kind:f.get('rkind')==='income'?'income':'expense',category:f.get('category')||'',account:f.get('account')||'',merchant:f.get('merchant')||'',freq:f.get('freq')||'month',interval:Math.max(1,Number(f.get('interval')||1)),start,end:endType==='never'?{type:'never'}:{type:endType,value:endType==='count'?Math.floor(Number(endRaw)):endRaw}};if(!old||old.start!==start)r.next=start;r.ended=false;const rx=recurringFromForm(r,f,!old);if(rx){alert(rx);return}if(recurringEnded(r))r.ended=true;if(old)state.recurring=state.recurring.map(x=>x===old?r:x);else state.recurring.push(r)}
  if(type==='loan'){
    const direction=f.get('direction')==='payable'?'payable':'receivable',amount=Math.abs(Number(f.get('amount')||0)),account=acct(f.get('account'));
    if(f.get('loanExisting')){const r=loanCreateExisting({direction,amount,person:f.get('person'),date:f.get('date'),dueDate:f.get('dueDate'),name:f.get('loanName'),note:f.get('note')});if(r.error){alert(r.error);return}}else{if(!amount||!account||!account.id){alert('請輸入有效的金額與帳戶');return}
    const loanId=id(),date=f.get('date')||selectedDate,person=f.get('person')||'未指定對象';
    const loan={id:loanId,person,direction,amount,paid:0,account:account.id,date,dueDate:f.get('dueDate')||'',name:f.get('loanName')||((direction==='receivable'?'借出給 ':'借入自 ')+person),note:f.get('note')||'',payments:[],status:'active'};
    state.loans.push(loan);
    account.balance += direction==='receivable' ? -amount : amount;
    state.transactions.push({id:id(),date,name:loan.name,amount,kind:'loan',loanId,direction,loanAction:direction==='receivable'?'lend':'borrow',account:account.id,note:loan.note,person,category:'',loanRecord:true});}
  }
  await save();closeModals();render();if(type==='loan'){window.__mozeLoanFilter='all';window.__mozeSelectedLoanId=type==='loan'?state.loans[state.loans.length-1].id:null;renderLoans();}
}
function txEffect(t){
  if(!t)return 0;
  if(t.kind==='expense')return -Math.abs(Number(t.amount||0));
  if(t.kind==='income')return Math.abs(Number(t.amount||0));
  if(t.kind==='transfer')return 0;
  if(t.kind==='loan')return t.loanAction==='lend'?-Math.abs(Number(t.amount||0)):Math.abs(Number(t.amount||0));
  if(t.kind==='loanPayment')return t.loanDirection==='receivable'?Math.abs(Number(t.amount||0)):-Math.abs(Number(t.amount||0));
  return 0;
}
function txTypeLabel(t){return t.kind==='expense'?'支出':t.kind==='income'?'收入':t.kind==='transfer'?'轉帳':t.kind==='loanPayment'?'收還款':'借還款'}
function txRow(t){let c=cat(t.category),effect=txEffect(t);return `<div class="row"><div class="row-left"><div class="mini-icon">${catIconHTML(c)}</div><div><b>${esc(t.name)}</b><div class="hint">${esc(t.merchant||t.person||'')} · ${esc(acct(t.account).name)}</div></div></div><div class="amount ${effect<0?'expense-text':effect>0?'income-text':''}">${effect>0?'+':effect<0?'−':''}${money(Math.abs(effect||t.amount||0))}</div></div>`}
function openDetail(id){let t=state.transactions.find(x=>String(x.id)===String(id));if(!t)return;window.detailId=t.id;let c=cat(t.category),project=t.project?(state.projects.find(p=>String(p.id)===String(t.project))?.name||'—'):'無專案',effect=txEffect(t);detailTitle.textContent=t.name;detailSubtitle.textContent=fmtDate(t.date);detailGrid.innerHTML=`<div class="detail-box"><small>金額</small><b class="${effect<0?'expense-text':effect>0?'income-text':''}">${effect>0?'+':effect<0?'−':''}${money(Math.abs(effect||t.amount||0))}</b></div>${t.feeIncluded&&(t.fee||t.discount)?`<div class="detail-box"><small>含費用／折扣</small><b>${t.fee?esc(t.feeName||'手續費')+' '+money(t.fee):''}${t.fee&&t.discount?'　':''}${t.discount?esc(t.discountName||'折扣')+' −'+money(t.discount):''}</b></div>`:''}<div class="detail-box"><small>類型</small><b>${txTypeLabel(t)}</b></div><div class="detail-box"><small>分類</small><b>${esc(c.icon)} ${esc(c.name)}</b></div><div class="detail-box"><small>帳戶</small><b>${esc(acct(t.account).name)}</b></div><div class="detail-box"><small>專案</small><b>${project}</b></div><div class="detail-box"><small>商家／對象</small><b>${esc(t.merchant||t.person||'—')}</b></div><div class="detail-box"><small>時間</small><b>${esc(t.time||'—')}</b></div>${t.installment?`<div class="detail-box"><small>分期</small><b>${installmentLabel(t)}</b></div>`:''}${t.kind==='transfer'?`<div class="detail-box"><small>轉入</small><b>${acctName(acct(t.toAccount))} ${acctMoney(Number(t.toAmount??t.amount),acct(t.toAccount))}</b></div>${t.fee?`<div class="detail-box"><small>手續費</small><b>${money(t.fee)}</b></div>`:''}`:''}<div class="detail-box"><small>標籤</small><b>${tagsHtml(t)||'—'}</b></div><div class="detail-box detail-wide"><small>備註</small><b>${esc(t.note||'—')}</b></div>`;if(typeof txDetailExtra==='function')txDetailExtra(t);detailBg.classList.add('open')}
function renderTransactions(){txFillAdvanced();const f=txFilterState(),all=txSearchRun(f),ts=all.slice(0,txLimit);let summary=txSummaryHTML(txSearchSummary(all),ts.length,f);let groups={};ts.forEach(t=>(groups[t.date]??=[]).push(t));let body=Object.entries(groups).map(([date,list])=>{let dayOut=list.filter(t=>t.kind==='expense').reduce((s,t)=>s+t.amount,0),dayIn=list.filter(t=>t.kind==='income').reduce((s,t)=>s+t.amount,0);return `<div class="tx-group"><div class="tx-group-head"><b>${date}</b><span>${dayOut?'支出 '+money(dayOut):''}${dayIn?' · 收入 '+money(dayIn):''}</span></div>${list.map(t=>{let amount=txEffect(t);return `<div class="tx-entry ${bulkMode&&bulkSel.has(String(t.id))?'bulk-selected':''}" data-txid="${t.id}"><div class="tx-icon">${bulkMode?`<input type="checkbox" class="bulk-check" aria-label="選取" ${bulkSel.has(String(t.id))?'checked':''}>`:esc(cat(t.category).icon)}</div><div><div class="tx-name">${esc(t.name)}</div><div class="tx-meta">${esc(t.merchant||t.person||'—')} · ${esc(acct(t.account).name)}${esc(t.project?' · '+(state.projects.find(p=>String(p.id)===String(t.project))?.name||''):'')}${txExtra(t)}</div></div><div class="tx-type">${txTypeLabel(t)}</div><div class="tx-actions"><b class="tx-amount ${amount<0?'expense-text':amount>0?'income-text':''}">${amount>0?'+':amount<0?'−':''}${money(Math.abs(amount||t.amount))}</b></div></div>`}).join('')}</div>`}).join('')||'<div class="panel empty">找不到符合條件的交易</div>';txTable.innerHTML=summary+`<div class="tx-groups">${body}</div>`+(all.length>ts.length?`<div class="tx-more"><button type="button" class="secondary" id="txMore">再顯示 ${Math.min(300,all.length-ts.length).toLocaleString()} 筆（還有 ${(all.length-ts.length).toLocaleString()} 筆）</button></div>`:'');document.querySelectorAll('.tx-entry').forEach(row=>row.onclick=()=>{if(!bulkMode)return openDetail(row.dataset.txid);const k=String(row.dataset.txid);if(bulkSel.has(k))bulkSel.delete(k);else bulkSel.add(k);row.classList.toggle('bulk-selected',bulkSel.has(k));const cb=row.querySelector('.bulk-check');if(cb)cb.checked=bulkSel.has(k);renderBulkBar()});renderBulkBar();document.getElementById('txMore')?.addEventListener('click',()=>{txLimit+=300;renderTransactions()});document.getElementById('txClearFilters')?.addEventListener('click',()=>{txClearAdvanced();txLimit=300;renderTransactions()});document.getElementById('txExport')?.addEventListener('click',downloadTxExport)}
function renderAccountDetail(){const el=document.getElementById('accountDetail'),a=selectedAccountId?acct(selectedAccountId):null;if(!el||!a||!a.id||a.type==='card'){if(el)el.hidden=true;return}const ts=state.transactions.filter(t=>String(t.account)===String(a.id)||String(t.toAccount)===String(a.id)).sort((x,y)=>y.date.localeCompare(x.date));const income=ts.filter(t=>t.kind==='income'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);const expense=ts.filter(t=>t.kind==='expense'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);const transferIn=ts.filter(t=>t.kind==='transfer'&&String(t.toAccount)===String(a.id)).reduce((s,t)=>s+t.amount,0);const transferOut=ts.filter(t=>t.kind==='transfer'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0);el.hidden=false;el.innerHTML=`<div class="account-detail-head"><div class="account-detail-title"><div class="account-detail-icon">${svgForAccount(a)}</div><div><h3><select class="acct-switch" data-acct-switch aria-label="切換帳戶">${acctOrdered(state.accounts).map(x=>`<option value="${esc(x.id)}"${x.id===a.id?" selected":""}>${acctName(x)}</option>`).join("")}</select></h3><div class="hint">${acctTypeLabel(a)} · 帳戶明細</div></div></div><span><button type="button" class="icon" data-acct-menu="${esc(a.id)}" aria-label="更多功能">⋯</button><button type="button" class="secondary" data-close-account-detail>關閉</button></span></div><div class="account-detail-summary"><div class="account-summary-box"><span>目前餘額</span><b>${acctMoney(a.balance,a)}</b></div><div class="account-summary-box"><span>收入</span><b class="income-text">${money(income+transferIn+ts.filter(t=>t.kind==='loan'&&t.loanAction==='borrow'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0)+ts.filter(t=>t.kind==='loanPayment'&&t.loanDirection==='receivable'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0))}</b></div><div class="account-summary-box"><span>支出</span><b class="expense-text">${money(expense+transferOut+ts.filter(t=>t.kind==='loan'&&t.loanAction==='lend'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0)+ts.filter(t=>t.kind==='loanPayment'&&t.loanDirection==='payable'&&String(t.account)===String(a.id)).reduce((s,t)=>s+t.amount,0))}</b></div></div><div class="acct-quick">${a.type==='cash'?'':`<button type="button" class="secondary" data-transfer="提款" data-account="${esc(a.id)}">⬆ 提款</button>`}<button type="button" class="secondary" data-transfer="存款" data-account="${esc(a.id)}">⬇ ${a.type==='cash'?'存入現金':'存款'}</button><button type="button" class="secondary" data-transfer="轉帳" data-account="${esc(a.id)}">⇄ 轉帳</button></div>${acctInfoHTML(a)}${acctPaneHTML(a)}`;el.querySelector('[data-close-account-detail]')?.addEventListener('click',()=>{selectedAccountId=null;el.hidden=true;renderAccounts()})}

// Loan page event delegation. No dynamically-created inline onclick handlers.
document.addEventListener('click',async e=>{
  const filter=e.target.closest('[data-loan-filter]');
  if(filter){window.__mozeLoanFilter=filter.dataset.loanFilter||'all';window.__mozeSelectedLoanId=null;renderLoans();return}
  const close=e.target.closest('[data-loan-close]');
  if(close){window.__mozeSelectedLoanId=null;renderLoans();return}
  const full=e.target.closest('[data-loan-full]');
  if(full){const id=window.__mozeSelectedLoanId,loan=(state.loans||[]).find(l=>String(l.id)===String(id));if(loan){const el=document.getElementById('loanPaymentAmount');if(el)el.value=loanOutstanding(loan)}}
  const findLoan=v=>(state.loans||[]).find(l=>String(l.id)===String(v));
  const payDel=e.target.closest('[data-loan-pay-del]');
  if(payDel){const loan=findLoan(window.__mozeSelectedLoanId),p=loan?.payments.find(x=>String(x.id)===String(payDel.dataset.loanPayDel));if(!loan||!p)return;const t=loan.historicalOnly?null:loanPaymentTx(loan,p);const txs=loan.historicalOnly?loanTxs(loan):t?[t]:[];if(!confirm(`刪除這筆${loanActionLabel(loanDirection(loan))}記錄？\n\n${p.date||''} ${money(p.amount)}\n帳戶餘額還原：${loanEffectText(txs)}${loan.historicalOnly?'\n\n這是匯入時建立的歷史記錄，會連同這筆借還款一起刪除。':''}${!loan.historicalOnly&&!t?'\n\n⚠️ 找不到對應的交易，只會刪除記錄，不會調整帳戶餘額。':''}`))return;const r=removeLoanPayment(loan,p);if(r.removedLoan)window.__mozeSelectedLoanId=null;await save();render();return}
  const del=e.target.closest('[data-loan-delete]');
  if(del){const loan=findLoan(del.dataset.loanDelete);if(!loan)return;const txs=loanTxs(loan);if(!confirm(`刪除「${loan.person||'未指定對象'}」的這筆${loanLabel(loanDirection(loan))}？\n\n會一併刪除 ${txs.length} 筆相關交易（借出／借入與所有收還款）。\n帳戶餘額還原：${loanEffectText(txs)}`))return;removeLoan(loan);window.__mozeSelectedLoanId=null;window.__mozeLoanEditId=null;await save();render();return}
  const resume=e.target.closest('[data-loan-resume]');
  if(resume){const loan=findLoan(resume.dataset.loanResume);if(!loan)return;loan.status='';refreshLoanStatus(loan);await save();render();return}
  const editBtn=e.target.closest('[data-loan-edit]');
  if(editBtn){window.__mozeLoanEditId=editBtn.dataset.loanEdit;renderLoans();return}
  if(e.target.closest('[data-loan-edit-cancel]')){window.__mozeLoanEditId=null;renderLoans();return}
  const editSave=e.target.closest('[data-loan-edit-save]');
  if(editSave){const loan=findLoan(editSave.dataset.loanEditSave);if(!loan)return;const v=id=>String(document.getElementById(id)?.value||'').trim();const person=v('loanEditPerson')||'未指定對象';loan.person=person;loan.name=v('loanEditName')||loan.name;loan.dueDate=v('loanEditDue');loan.note=v('loanEditNote');for(const t of loanTxs(loan))t.person=person;window.__mozeLoanEditId=null;await save();render();return}
  const action=e.target.closest('[data-loan-action]');
  if(action){e.preventDefault();e.stopPropagation();selectLoan(action.dataset.loanAction);return}
  const row=e.target.closest('[data-loan-id]');
  if(row){if(!row.closest('#view-loans'))nav('loans');selectLoan(row.dataset.loanId);return}
  const stop=e.target.closest('[data-loan-stop]');
  if(stop){const loan=(state.loans||[]).find(l=>String(l.id)===String(stop.dataset.loanStop));if(loan&&confirm(`確定停止追蹤「${loan.person}」的這筆${loanLabel(loanDirection(loan))}？`)){loan.status='stopped';await save();render()};return}
  const confirmBtn=e.target.closest('[data-loan-confirm]');
  if(confirmBtn){
    const loan=(state.loans||[]).find(l=>String(l.id)===String(confirmBtn.dataset.loanConfirm));if(!loan)return;const lv=k=>document.getElementById(k)?.value;const r=loanSettle(loan,{amount:lv('loanPaymentAmount'),account:lv('loanPaymentAccount'),date:lv('loanPaymentDate')||selectedDate,note:lv('loanPaymentNote')||'',over:lv('loanPaymentOver'),under:lv('loanPaymentUnder')});if(r.error){alert(r.error);return}await save();render();window.__mozeSelectedLoanId=loan.id;renderLoans();document.getElementById('loanDetailPanel')?.scrollIntoView({behavior:'smooth',block:'nearest'});return}
});

