  if (by === 'sub') return anParts(t).map(([c, v]) => [String(c), cat(c).name, v]);
  if (by === 'project') { const l = (state.projects || []).filter(p => projMatch(p, t)); return l.length ? l.map(p => [String(p.id), p.name, anValue(t)]) : [['', '無專案', anValue(t)]]; }
