function prefSyncOn() { return !!prefs().prefSync && String(prefs().prefSyncOwner ?? prefSyncUser()) === prefSyncUser(); }
function prefSyncHost() { return (state?.categories || []).find(c => c.id === '__prefs__') || null; }
