function apRow(r, a) { const t = r.t, c = cat(t.category); return `<button type="button" class="account-detail-row" data-tx-open="${esc(t.id)}" data-pb-date="${t.date}"><span class="account-detail-date">${fmtDate(t.date)}</span><div class="mini-icon">${catIconHTML(c)}</div><div><b>${esc(t.name)}</b><div class="tx-meta">${esc(t.merchant || t.person || t.note || '—')}${t.kind === 'transfer' ? ` · ${acctName(acct(t.account))} → ${acctName(acct(t.toAccount))}` : ''}</div></div><div class="amount ${r.effect < 0 ? 'expense-text' : r.effect > 0 ? 'income-text' : ''}">${r.effect > 0 ? '+' : ''}${acctMoney(r.effect, a)}<small class="pb-after">${acctMoney(r.after, a)}</small></div></button>`; }
