  if (lend || owe) { out.tab = owe ? 'payable' : 'receivable'; const p = owe ? owe[2] : /借給\s*([^\s\d]{1,6}?)(?=\s|\d|$)/.exec(s)?.[1] || lend[1] || ''; out.person = p; out.preset = owe ? '借入' : /代付|幫/.test(s) ? '代付' : '借出'; }
