  const name = rest.replace(/(我|今天|剛剛|買了?|吃了?|喝了?|花了?|付了?|用了?|刷卡|刷|搭了?|繳了?|收到|的|元|塊錢?|現金付)/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 30);
