// Direction of a swipe, or '' when it is too short / too diagonal.
function swipeDir(dx, dy, min) { const a = Math.abs(dx), b = Math.abs(dy), m = min || 60; return a >= m && a > b * 1.6 ? (dx > 0 ? 'right' : 'left') : b >= m && b > a * 1.6 ? (dy > 0 ? 'down' : 'up') : ''; }
