  o.hidden = !g; o.disabled = !g; if (!g && el.postMode.value === 'offset') el.postMode.value = 'now'; else if (g && el.postMode.value === 'now' && !editId && el.postMode.dataset.user !== '1') el.postMode.value = 'offset';
