function projBudgetList(p) { return (state.budgets || []).filter(b => { const x = budgetNorm({ ...b }); return (x.scope === 'project' && String(x.project) === String(p.id)) || (x.scope === 'category' && String(x.inProject) === String(p.id)); }); }
