function invRoc(key) { const [y, m] = key.split('-').map(Number), p2 = v => String(v).padStart(2, '0'); return `${y - 1911} 年 ${p2(m)} － ${p2(m + 1)} 月`; }
function invSource(inv) { return inv.carrier || (inv.code ? '紙本發票' : '手動輸入'); }
