  const tabs = `<div class="entry-tabs">${[['todo', `待處理 ${todo.length || ''}`], ['done', `已對應 ${done.length || ''}`], ['skip', `已略過 ${skip.length || ''}`], ['all', `全部明細 ${all.length || ''}`]].map(([k, l]) => `<button type="button" data-bank-tab="${k}" class="${k === s.tab ? 'active' : ''}">${l}</button>`).join('')}</div>`;
